import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

public class OrderProcessor {
    private final ConcurrentMap<String, UserSession> activeSessions = new ConcurrentHashMap<>();

    public UserSession getOrCreateSession(String userId) {
        // computeIfAbsent is atomic in ConcurrentHashMap, preventing race conditions
        // without locking the entire map structure.
        return activeSessions.computeIfAbsent(userId, id -> {
            return loadSessionFromDatabase(id);
        });
    }

    private UserSession loadSessionFromDatabase(String userId) {
        return new UserSession(userId);
    }

    public static class UserSession {
        private final String id;
        public UserSession(String id) { this.id = id; }
    }
}
